namespace RonSijm.FluidHumidifier.Factories.WorkSpaces;

public class DirectoryFactory(string resourceName = null, Action<Humidifier.WorkSpaces.Directory> factoryAction = null) : ResourceFactory<Humidifier.WorkSpaces.Directory>(resourceName)
{

    internal InnerDirectorySelfservicePermissionsFactory SelfservicePermissionsFactory { get; set; }

    internal InnerDirectoryStreamingPropertiesFactory StreamingPropertiesFactory { get; set; }

    internal InnerDirectoryMicrosoftEntraConfigFactory MicrosoftEntraConfigFactory { get; set; }

    internal InnerDirectorySamlPropertiesFactory SamlPropertiesFactory { get; set; }

    internal InnerDirectoryDefaultWorkspaceCreationPropertiesFactory WorkspaceCreationPropertiesFactory { get; set; }

    internal InnerDirectoryActiveDirectoryConfigFactory ActiveDirectoryConfigFactory { get; set; }

    internal InnerDirectoryWorkspaceAccessPropertiesFactory WorkspaceAccessPropertiesFactory { get; set; }

    internal InnerDirectoryCertificateBasedAuthPropertiesFactory CertificateBasedAuthPropertiesFactory { get; set; }

    protected override Humidifier.WorkSpaces.Directory Create()
    {
        var directoryResult = CreateDirectory();
        factoryAction?.Invoke(directoryResult);

        return directoryResult;
    }

    private Humidifier.WorkSpaces.Directory CreateDirectory()
    {
        var directoryResult = new Humidifier.WorkSpaces.Directory
        {
            GivenName = InputResourceName,
        };

        return directoryResult;
    }
    public override void CreateChildren(Humidifier.WorkSpaces.Directory result)
    {
        base.CreateChildren(result);

        result.SelfservicePermissions ??= SelfservicePermissionsFactory?.Build();
        result.StreamingProperties ??= StreamingPropertiesFactory?.Build();
        result.MicrosoftEntraConfig ??= MicrosoftEntraConfigFactory?.Build();
        result.SamlProperties ??= SamlPropertiesFactory?.Build();
        result.WorkspaceCreationProperties ??= WorkspaceCreationPropertiesFactory?.Build();
        result.ActiveDirectoryConfig ??= ActiveDirectoryConfigFactory?.Build();
        result.WorkspaceAccessProperties ??= WorkspaceAccessPropertiesFactory?.Build();
        result.CertificateBasedAuthProperties ??= CertificateBasedAuthPropertiesFactory?.Build();
    }

} // End Of Class

